import{Handle}from"../primitives/Handle.js";import{random}from"../tools/random.js";class Envelope extends Handle{constructor(){super(),this.defaultFrom=()=>[this.closest("[data-sampler-blam]")]}parseCurve(){this.pairs=this.curve.replaceAll(", ",",").split(",").map(pair=>pair.split(" ").map(string=>parseFloat(string)))}handle(event){if(random.chance(this.chance))for(const to of this.toElems){let param=to?.params[this.prop];if(!param)return;let data=event.detail,length=data.clipDuration,time=data.time,x=this.beats?this.beat:length;param.cancelScheduledValues(time);for(let pair of this.pairs)param.linearRampToValueAtTime(pair[0],time+pair[1]*x)}}get curve(){return this.getAttribute("curve")}set curve(value){this.setAttribute("curve",value)}get beats(){return this.hasAttribute("beats")}set beats(value){this.toBoolean("beats",value)}static get observedAttributes(){return["curve"]}attributeChangedCallback(name){"curve"===name&&this.parseCurve()}}export{Envelope};